// Copies the contents of a codeblock generated by Chroma syntax
// highlighter. Pass is the Id names of the surrounding code
// block / div and an Id name for ani interactive element that
// will inform the user the copy has occurred.

async function copyCodeToClipboard(elementId, buttonId) {
  const ele = document.getElementById(elementId);
  const btn = document.getElementById(buttonId);

  if (ele && btn) {
    const codeToCopy = ele.querySelector(
      ":last-child > .lntd > code",
    ).innerText;
    try {
      const result = await navigator.permissions.query({ name: "clipboard-write" });
      if (result.state == "granted" || result.state == "prompt") {
        await navigator.clipboard.writeText(codeToCopy);
      } else {
        copyCodeBlockExecCommand(codeToCopy, ele);
      }
    } catch (_) {
      copyCodeBlockExecCommand(codeToCopy, ele);
    } finally {
      codeWasCopied(btn);
    }
  }
  else{
    console.log("Failed to copy the code block. Id's weren't found.")
  }
}

// Interaction to let them know we copied the code for them.
// TODO: How about an animation?

function codeWasCopied(button) {
  button.blur();
  button.innerText = "Copied!";
  setTimeout(function () {
    button.innerText = "Copy";
  }, 2000);
}

// Backup routine to be used for copying if the permissions for
// copying to the clipboard are not available.

function copyCodeBlockExecCommand(codeToCopy, highlightDiv) {
  const textArea = document.createElement("textArea");
  textArea.contentEditable = "true";
  textArea.readOnly = "false";
  textArea.className = "copyable-text-area";
  textArea.value = codeToCopy;
  highlightDiv.insertBefore(textArea, highlightDiv.firstChild);
  const range = document.createRange();
  range.selectNodeContents(textArea);
  const sel = window.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
  textArea.setSelectionRange(0, 999999);
  document.execCommand("copy");
  highlightDiv.removeChild(textArea);
}
